-- Fase 1 (extensao) -- metadados de protocolo (name, objective, description).
-- docs/PROTOCOL_METADATA_TRANSLATIONS_DRAFT_20260801.md
-- Traduzido diretamente (sem auditoria externa -- conteudo de baixa ambiguidade,
-- decisao do lider do projeto, 2026-08-01). 30 protocolos + 5 objetivos distintos
-- x 3 idiomas = 195 linhas.
-- curated = true: nunca sobrescrito por escrita de runtime.
-- Reaproveita a mesma exercise_content_translations -- chave e (source_text,
-- source_locale, target_locale), agnostica de qual tela/tabela originou o texto.

on conflict (source_text, source_locale, target_locale)
do update set translated_text = excluded.translated_text, curated = true;
